int levenshtein(const char *a, const char *b) {
    int n = (int)strlen(a);
    int m = (int)strlen(b);

    // Initialize the first row and column with costs
    int d[n + 1][m + 1];
    for (int i = 0; i <= n; i++) {
        d[i][0] = i;
    }
    for (int j = 0; j <= m; j++) {
        d[0][j] = j;
    }

    // Compute the Levenshtein distance using a single pass
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            int cost = a[i - 1] == b[j - 1] ? 0 : 1;
            d[i][j] = fmin(fmin(d[i - 1][j] + 1, d[i][j - 1] + 1), d[i - 1][j - 1] + cost);
        }
    }

    // The result is in the bottom-right cell
    int result = d[n][m];

    return result;
}
